    "id": "motion-b31d078a-4e5e-461e-8b43-3101ee0a2f93",
    "name": "A New Era of No-Code",
    "summary": "以球体作为视觉向导，在分层网页、表单和流程空间中穿行。界面不只是截图，而是具有前后距离的可组合平面。",
    "style": "少量品牌字标；主体是窗口线框、控件与空间几何",
    "reviewFocus": "将网页拆成底板、图片、标题与线框，沿深度方向留距离。小球沿共同透视方向穿行，近处平面移动更快，远处更慢。；门户与透明立方体负责换空间，进入工作台后用输入栏、按钮和控件组建立功能感。蓝紫为主，粉、青、黄只分配给局部内容。；后段让数据轨迹在窗口、表单与用户节点之间流动。路径要有明确起点和终点，球体抵达后才触发下一个窗口的状态。；可换为产品模块或业务卡，但保留一个持续出现的球体或小物件。准备可分层的界面元素，不将整屏图片当成所有空间层。",
