    "name": "HyperOS 官网界面动效 1",
    "summary": "从材质特写进入手机界面，再把相同圆角和透明层扩展到图标、小组件与多设备。",
    "style": "无衬线窄长时间数字；控件和图标圆角一致，透明层保持明亮",
    "reviewFocus": "从材质特写进入手机界面，再把相同圆角和透明层扩展到图标、小组件与多设备。；先展示玻璃边缘与曲面，再落到锁屏、音乐和控制中心。透明层保留边缘高光与背景色透出，正文比背景更清楚，不让折射干扰按钮含义。；音乐卡和桌面小组件从手机中被放大展示，再回到完整界面。整体位置与内容一一对应，漂浮组件使用不同深度但同一光照方向。",
