    "style": "无文字的满幅图形；锋利折角与软波浪对比",
    "reviewFocus": "同类形状用固定间距重复，折点上下移动时相邻条带保持对应。图案超出画幅边缘，避免出现外框。；黄蓝、黄红、深浅粉、深浅蓝分别成组。切换时同时更换形状族与色组，组内则只做形变和位移，保持整体性。；折块使用短促错位；波浪用连续起伏；圆点以不同半径穿过画面。新品牌可替换色板，但保留每组形状的动作特性和满幅密度。",
