    "reviewFocus": "每个按钮都有局部凹口与斜边，堆叠时保持相近宽度和小间距。标签贴近轮廓平直的区域，方向箭头留在另一端。；三个按钮短促滑出后，Gradient Fill 先返回，再加入 Fractal Noise 与 Halftone。黑底与白色细轮廓保持极简，移动时标签和箭头跟随容器。；适合短效果名或工具名；内容变长时优先加宽模块，不让标签碰到凹口。循环开始与结束使用同一排列。",
