    "id": "motion-36220499-8ac9-4a39-afb9-35bfba462abb",
    "name": "数字动效 · 6.1 秒",
    "summary": "先用三个大数字连续倒计时，再拉开成为一套九宫格数字，展示同一家族的折线与圆角。",
    "style": "粗重自定义数字，圆角与折线结合；黑白强对比",
    "reviewFocus": "3、2、1 分别使用紫、荧光黄、玫红底，黑色大数字占据中央。字符变化短促，停顿清晰，字形转折可以轻微折叠但不削弱数字辨认。；倒计时结束切黑底，白色数字按从左到右、从上到下补齐。格子中心不移动，内部轮廓逐步转成最终数字；最后放大 3 回到开头形成循环。；替换为章节编号或计数时，保持统一笔画宽、圆角和斜切角。网格最多九项，新字不挤占相邻格。",
    "useCase": "品牌宣传",
