    "style": "温暖米白背景，咖啡品牌使用褐色摄影与衬线字，平台标记橙红。",
    "reviewFocus": "输入创建咖啡网站后，继续要求演示稿和发布图。三类成果共享照片、褐色色盘与衬线标题，用内容一致性说明上下文复用。；网站先居中，再扇开多页 deck；下一次输入在已有成果之间出现，最后排成三张竖版海报。不要每段都彻底清空画面。；外层米白留白充足，输入卡用细阴影，橙红平台标记固定在右上。结束时回到人物照片，配一条短结论即可。",
