    "reviewFocus": "前半段用不同大小的字母、条带和几何铺满画面，整体缩小后，碎片向中央单词的基线靠拢。元素退出与新字母出现错开进行。；黑色单词居中，字号明显小于开头碎片；纸片和线条退到极低对比，只留下阅读所需的笔画。更换关键词时重新分配字母宽度，不保持原碎片机械平移。",
