    "summary": "以同一个标志做创作风格轮播，从细线、金属和花卉到图像拼贴；统一的位置和留白把变化收成一个系列。",
    "style": "以标志轮廓与材质为主；文字只是拼贴或编辑辅助",
    "reviewFocus": "每种材质可以完全不同，但标志中心与最大外接框保持相近。白色四周留足空间，花卉与碎片只在局部扩出。；沿弧线收缩、展开和断开，使下一种风格接在相近位置。以两三帧材质变化制造速度，较完整版本停留稍长；不额外叠标题。；可替换为品牌的不同创作领域，每组只选一个材质主意。不要在同一帧混合所有风格。",
    "useCase": "品牌宣传",
    "presentation": "图形动效",
