    "summary": "三张模板横排，中央卡完整显示，两侧只露一部分并压暗。切换时整条轨道横向滑动，到位后才恢复中央卡的亮度。",
    "style": "黑色画廊底；卡片各有独立字体，名称与 Agent 标签在卡片下方。",
