    "summary": "玻璃本身固定，手和容器从后方经过；细密方格把轮廓分成错位的小段。全景交代框架，近景让纹理与失真关系清楚可见。",
    "style": "中性灰白摄影空间，细密压纹玻璃，棕肤色只作为玻璃后的移动参照。",
    "reviewFocus": "玻璃本身固定，手和容器从后方经过；细密方格把轮廓分成错位的小段。全景交代框架，近景让纹理与失真关系清楚可见。；灰白空间与侧向软光凸显凹凸玻璃，金属竖杆提供稳定边界。移动速度较慢，避免动作模糊掩盖压纹。；可以换成瓶、花、手部或彩色几何体；玻璃网格始终不动，失真随后方对象的位置变化。结尾停在安静的物体状态。",
