    "reviewFocus": "先把完整长网址放入渐变胶囊，随后推近句点。红点离开文字后仍保留颜色与中心，成为下一组圆形图案的起点。；摄影可用光圈，游戏可用像素格，旅行可用地平线，媒体可用色条。后缀固定在中心留白，图案在其周围运动，避免图案盖住短词。；紫、黄、红、粉、绿按段落切换，黑字或白字要与底色对比。地址胶囊可横向伸长，但最终后缀保持大字号与充足留白。；选择新业务真正适用的后缀或关键词，并为它安排一个可理解的几何隐喻。结尾收回点和品牌，结束图形例举。",
    "useCase": "品牌宣传",
    "presentation": "界面动效, 文字动效, 图形动效",
