    "id": "motion-e8b823ee-4201-4eda-a07b-e615407eb80e",
    "name": "Introducing Glean",
    "summary": "先展示助理理解个人任务，再把个人偏好扩展为人员、项目和数据的企业关系图。",
    "style": "中等字重无衬线；紫色陈述句与白色结果卡分层",
    "reviewFocus": "粉紫与米白渐变背景上保留细网格。提示栏输入后扩成白色结果卡，让策划方案或团队更新占据主要阅读时间，标题只在任务切换时出现。；先以单个人物为圆心放置写作、思考等偏好，再拉远加入人员、项目、数据与任务节点。连线随节点入场生长，近景文字清楚后再缩小成整体。；网络解释上下文，下一段仍要回到提示栏、流程和工具入口。将复杂图谱与简洁任务界面交替，不让所有镜头都变成漫游关系图。；替换人物、项目和数据源时，按真实关联连线。个人写作习惯与组织资源分别保留一个示例，结果文本只需展示最关键段落。",
