    "id": "motion-f53dad52-9f20-42c5-b5c3-00743ea475b3",
    "name": "Jitter Superagents｜产品能力展示",
    "summary": "把一句操作要求与画布上的变化放在一起：重混模板、排列圆点、偏移轨道，最后扩展到不同尺寸和语言。",
    "style": "紧凑粗体标题；画布作品字形随模板，工具提示采用小字",
    "reviewFocus": "模板重混前后保持内容结构；圆点排列由散乱转圆环，后续动作继续作用于这组点。指令框靠近画布，避免孤立的聊天截图。；轨道偏移需要同时看到条带与时间游标；尺寸适配需要保留同一标题和主图，在横、竖、方画板里重新排布。；单个画板操作讲清后，再拉远为多尺寸、多语言矩阵。黑白底承托彩色作品，蓝色只标记代理反馈与操作入口，批量导出标签盖在矩阵前。；准备可拆开的标题、图像和图形层，以及每个尺寸的重排规则。将批量变体做成同一内容家族，不用随机不同作品填数。",
    "useCase": "产品演示",
    "presentation": "界面动效",
    "brand": "Jitter",
