    "summary": "多支彩色光标描出字母曲线，黑色节点端点留在字形上。完整标题随后收成单张空白节点，把图形隐喻接入真实操作。",
    "style": "浅色点阵画布、黑色节点线条、多用户光标使用粉蓝紫橙。",
    "reviewFocus": "多支彩色光标描出字母曲线，黑色节点端点留在字形上。完整标题随后收成单张空白节点，把图形隐喻接入真实操作。；从同一源节点拉线，光标名称和线条颜色一一对应。新节点出现后再显示生成图片，继续从结果节点派生。；图谱扩展时适度缩小整体，让多个结果同时可见；结束时只保留成果缩略图和一句发布结论。更换主题时沿用同源多分支。",
