    "name": "OKX AI — AI agents can already work, create, and earn.",
    "summary": "从一个人扩展到一组代理，再进入服务选择和履约过程。紫色块贯穿人物、目录与选中状态，保持同一个行动主线。",
    "style": "等宽短句与粗无衬线口号交替；流程状态用清楚的小标签",
    "reviewFocus": "灰度人物与植物画面承托简短主张，单个人复制成列后切到代理网格。紫色矩形作为重音遮片与词块，黑白图像保持低饱和。；类别列表只突出一项，再进入代理列表和详情。名称、评分、价格与操作按钮要放在同一信息区，焦点由紫色高亮传递。；打开、接受、提交、审查和完成依次点亮，当前状态向右推进。最后给一句结算主张再落品牌，不混入新的任务或代理。；可迁移到创作、研发或业务服务市场。演示价格、评分和状态使用清楚的示例内容，保持目录→详情→执行→完成的结构。",
