    "id": "motion-13ba3942-fd15-40ee-9638-03d1376514db",
    "name": "Persimmon — a model that simulates people",
    "summary": "先用一张果实海报表现个体，再拉开成许多差异化样本；让粒子跨越海报边界，完成从个体到互动的叙事。",
    "style": "轻衬线叙事句；小字标签与最后品牌名对齐",
    "reviewFocus": "暖白墙面上放一张竖海报，标题在上，柿子在中央，色点在底部。自然光与影子缓慢移动，果实由不同疏密的彩点组成。；拉远后整齐排列不同海报，保持相同版式而改变果实内部纹理。第二句主张出现时，彩点离开自己的海报向邻近区域流动。；实物与海报同框后，切到奶油色底上的点状果实和产品名。新主题可换象征物，但一人、多样本、互动三步要由同一视觉元素贯穿。",
