    "name": "TIDAL｜文字主视觉 15 秒版",
    "summary": "在十五秒内保留致意、立场、音乐、创作者与听众五个重音；每次只读一组词。",
    "style": "极粗窄体大写字；短词以巨大字号占据中心",
    "reviewFocus": "主词使用极粗窄体，尽量一至两行；连接词缩小放在上下或侧边。文字可在入场时裁切，但落定的关键词要完整可读。；菱形从中心扩张覆盖画面，或四角向内合拢。用青绿／深绿和亮紫／深紫交替分组，柠檬黄突出情绪重词。；把前一关键词的放大或移出当作下一句的入场空间。ARTISTS 与 FANS 使用相似形变形成呼应，收尾回到稳定的三行品牌句。；可替换品牌和社群称谓，保留呼喊式短句与强弱词层级。缩短长版本时优先删除完整例举组，留下核心承诺，不把每句都加倍加速。",
    "useCase": "品牌宣传",
