    "style": "主角为品牌标与几何群；不额外加入长文字",
    "reviewFocus": "黑底中先描出中心标志的局部亮边，尺寸保持小。临界点直接扩大空间，亮度与物体数量一起提升，形成明确反差。；球、花瓣、环和长条沿径向展开，近处物体更大并允许裁出画幅。绿、紫、粉、青分配给不同形状，中心标志保持辨认空间。；外围图形缩向中心并褪去色彩，最后只剩白色标志。替换时选择一个中心标志和少量重复几何，不让字句打断六秒的收放动作。",
