    "reviewFocus": "用复制失控的桌面表现繁杂工作，再让一个开关把所有噪声整理成少量完成的流程。；一个窗口引出代码和文件，随后沿对角线形成层层残影。文件名越加越长，窗口互相压住；指针穿行，饱和粉紫背景逐渐加入橙色。；OFF 状态让画面维持拥挤，切到 ON 后整体清空，三条流程在中心按行对齐。流程再合成一条，留下图标、短线与完成勾；不继续保留混乱桌面的碎片。",
